import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ListBatcherTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static List<String> listOf(String... values) {
        return new ArrayList<>(Arrays.asList(values));
    }

    public static void main(String[] args) {
        try {
            check("batch(5 items, 2)", "[[a, b], [c, d], [e]]",
                    ListBatcher.batch(listOf("a", "b", "c", "d", "e"), 2).toString());
            check("batch(4 items, 2) divides evenly", "[[a, b], [c, d]]",
                    ListBatcher.batch(listOf("a", "b", "c", "d"), 2).toString());
            check("batch size larger than list", "[[a, b, c]]",
                    ListBatcher.batch(listOf("a", "b", "c"), 9).toString());
            check("batch size of 1", "[[a], [b], [c]]",
                    ListBatcher.batch(listOf("a", "b", "c"), 1).toString());
            check("batch size of 0", "[]",
                    ListBatcher.batch(listOf("a", "b", "c"), 0).toString());
            check("empty input", "[]", ListBatcher.batch(listOf(), 3).toString());

            List<String> source = listOf("a", "b", "c");
            List<List<String>> batches = ListBatcher.batch(source, 2);
            batches.get(0).add("intruder");
            check("batches are independent of the input", 3, source.size());
            check("batch contents copied", "[a, b, intruder]", batches.get(0).toString());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

